import { EVENT_GLYPHS, type NsEvent } from "../types/events";

export function clockTime(ts: string): string {
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return "--:--:--";
  return d.toLocaleTimeString("en-GB", { hour12: false });
}

export function shortDate(ts: string | null | undefined): string {
  if (!ts) return "—";
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toLocaleString("en-GB", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

export function glyphFor(event: NsEvent): string {
  return EVENT_GLYPHS[event.event_type] ?? (event.severity === "critical" ? "🔴" : "·");
}

function str(payload: Record<string, unknown>, key: string): string | null {
  const v = payload[key];
  if (v === undefined || v === null) return null;
  return String(v);
}

/** Human-readable one-liner for the live ticker. Pure — no side effects. */
export function describeEvent(event: NsEvent): string {
  const p = event.payload ?? {};
  switch (event.event_type) {
    case "call_received":
      return `call received · ${str(p, "channel") ?? "voice"}`;
    case "case_ingested":
      return `case #${str(p, "case_number") ?? str(p, "case_id") ?? "?"} in`;
    case "entity_linked":
      return `entity link ${str(p, "entity") ?? ""}`.trim();
    case "mo_extracted":
      return `MO extracted · case #${str(p, "case_number") ?? "?"}`;
    case "case_linked": {
      const pair = Array.isArray(p.pair) ? (p.pair as unknown[]).join(" ↔ ") : "";
      return `linked ${pair} · w ${str(p, "score") ?? "?"}`;
    }
    case "cluster_formed":
      return `cluster formed (${str(p, "size") ?? "?"})`;
    case "campaign_proposed":
      return `CAMPAIGN PROPOSED (${str(p, "case_count") ?? "?"}) ${str(p, "code") ?? ""}`.trim();
    case "campaign_approved":
      return `validated by ${str(p, "approved_by") ?? "human"}`;
    case "campaign_rejected":
      return `rejected · ${str(p, "reason") ?? "no reason"}`;
    case "campaign_edited": {
      // The emitter puts `fields` in the payload specifically so this line can
      // name what a human changed. Without a case here it falls to the default
      // branch, which prints the first three keys — a raw UUID dump beside a
      // tidy glyph, which looks handled and is not.
      const fields = Array.isArray(p.fields) ? (p.fields as unknown[]).join(", ") : "";
      return `edited ${str(p, "code") ?? "campaign"}${
        fields ? ` · ${fields}` : ""
      } by ${str(p, "edited_by") ?? "human"}`;
    }
    case "artifact_compiled":
      return `compiled ${str(p, "name") ?? "artifact"} v${str(p, "version") ?? "?"}`;
    case "artifact_published": {
      const from = str(p, "from_version");
      const to = str(p, "version");
      return `${str(p, "name") ?? "artifact"} ${from ? `v${from}→v${to}` : `v${to}`}`;
    }
    case "artifact_rolled_back":
      return `rollback ${str(p, "name") ?? ""} → v${str(p, "version") ?? "?"}`;
    case "propagated":
    case "worker_consumed":
      return `→ ${str(p, "agent") ?? "agent"}`;
    case "mcp_call":
      return `${str(p, "caller") ?? "caller"} ${str(p, "tool") ?? "tool"}(role=${
        str(p, "role") ?? "?"
      }) · ${str(p, "latency_ms") ?? "?"} ms`;
    case "eval_completed":
      return `eval ${str(p, "label") ?? ""} ${str(p, "detected") ?? "?"}/${
        str(p, "total") ?? "?"
      }`;
    case "unrecognised_pattern":
      return `UNRECOGNISED PATTERN · ${str(p, "observations") ?? "1"} observation`;
    default: {
      const keys = Object.keys(p);
      if (!keys.length) return event.event_type;
      return `${event.event_type} · ${keys
        .slice(0, 3)
        .map((k) => `${k}=${String(p[k])}`)
        .join(" ")}`;
    }
  }
}

export function formatNumber(n: number): string {
  return n.toLocaleString("en-GB");
}

/** 12960 minutes → "9 d"; 41 → "41 min". Keeps the metric bar honest. */
export function humaniseDuration(value: number, unit: string): string {
  if (unit === "min") {
    if (value >= 1440) return `${Math.round((value / 1440) * 10) / 10} d`;
    if (value >= 60) return `${Math.round((value / 60) * 10) / 10} h`;
    return `${value} min`;
  }
  if (unit === "s") {
    if (value >= 86400) return `${Math.round((value / 86400) * 10) / 10} d`;
    if (value >= 3600) return `${Math.round((value / 3600) * 10) / 10} h`;
    if (value >= 60) return `${Math.round((value / 60) * 10) / 10} min`;
    return `${value} s`;
  }
  return `${formatNumber(value)} ${unit}`;
}
